/**
 * Минимальное объявление единственного встроенного модуля, который нужен
 * тестам: `@types/node` в проект не установлен (он потянул бы глобальные типы
 * Node в браузерную сборку), а `styles.css` через `?raw` в Vitest читается
 * пустым — Vite подменяет CSS заглушкой. Поэтому страж фокуса читает файл
 * стилей напрямую с диска и объявляет ровно ту функцию, которую использует.
 */
declare module "node:fs" {
  export function readFileSync(path: URL | string, encoding: "utf8"): string;
}
